BEGIN;
CREATE TABLE hero_slides(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, image_url text NOT NULL, alt_text text NOT NULL, target_url text, sort_order integer NOT NULL DEFAULT 0, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT false, CHECK(ends_at>starts_at));
CREATE TABLE announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, body text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT false, CHECK(ends_at>starts_at));
CREATE TABLE offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('PERCENT','FIXED')), value integer NOT NULL CHECK(value>0), minimum_order_paise integer NOT NULL DEFAULT 0 CHECK(minimum_order_paise>=0), max_discount_paise integer CHECK(max_discount_paise>0), redemption_limit integer CHECK(redemption_limit>0), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, active boolean NOT NULL DEFAULT false, CHECK(ends_at>starts_at));
CREATE TABLE offer_redemptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), offer_id uuid NOT NULL REFERENCES offers(id), order_id uuid NOT NULL UNIQUE REFERENCES orders(id), organization_id uuid NOT NULL REFERENCES organizations(id), discount_paise integer NOT NULL CHECK(discount_paise>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE loyalty_accounts(organization_id uuid PRIMARY KEY REFERENCES organizations(id), points_balance bigint NOT NULL DEFAULT 0 CHECK(points_balance>=0));
CREATE TABLE loyalty_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), order_id uuid REFERENCES orders(id), kind text NOT NULL CHECK(kind IN ('EARN','REDEEM','EXPIRE','REVERSE','ADJUST')), delta_points bigint NOT NULL CHECK(delta_points<>0), idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
